import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CCCdsIgc.js";const _=JSON.parse('{"title":"专家","description":"","frontmatter":{},"headers":[],"relativePath":"guide/experts.md","filePath":"guide/experts.md"}'),o={name:"guide/experts.md"};function l(s,a,n,d,p,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="专家" tabindex="-1">专家 <a class="header-anchor" href="#专家" aria-label="Permalink to &quot;专家&quot;">​</a></h1><p>专家是 IT 针对某个业务场景配好的 AI：有自己的工作方式、业务知识和名片，比如生产分析、质检、IT 运维、报表助手。</p><h2 id="召唤专家" tabindex="-1">召唤专家 <a class="header-anchor" href="#召唤专家" aria-label="Permalink to &quot;召唤专家&quot;">​</a></h2><ol><li>侧栏「<strong>专家</strong>」里浏览已发布的专家，可以按分类筛选、按热度排序、看「我用过的」；</li><li>点卡片看详情：负责什么、示例问题、版本、维护人；</li><li>点「<strong>召唤</strong>」或某个示例问题，进入这位专家的对话（固定是办事模式）。</li></ol><p>专家沿用你电脑上的技能、连接器和工具，安全规则和确认照旧，不会因为是专家就放宽。只做查询分析的专家是<strong>只读</strong>的，不会改任何东西。</p><h2 id="主助手自动派遣-it-开启后才有" tabindex="-1">主助手自动派遣（IT 开启后才有） <a class="header-anchor" href="#主助手自动派遣-it-开启后才有" aria-label="Permalink to &quot;主助手自动派遣（IT 开启后才有）&quot;">​</a></h2><p>在普通的办事对话里，主助手发现事情属于某位专家的职责时，会把子任务派给专家：</p><ul><li>对话里出现专家卡片，实时显示专家在做哪一步；</li><li>专家做完交回结论，每条结论都附有依据，系统会核验依据是否真实，分「已支持 / 仅来源核实 / 未核实」显示；</li><li>专家要用连接器查东西（比如 MES 查工单）时，开工前会问你一次：列出这次可能用到的查询，点「<strong>这次派遣内都直接执行</strong>」后专家就不再逐条问；点「用到时逐条问我」就和以前一样。命令、写文件、删除这类操作不在这张卡里，到时候照旧单独问；</li><li>专家每一步需要确认的操作照样弹确认，卡片上写明是哪位专家在请求；</li><li>你在这次任务里点过「<strong>本任务内不再询问</strong>」的操作（不管是在主助手还是哪位专家的卡片上点的），主助手和派出去的专家都不再问；删除、覆盖这类高危操作照旧每次都问，任务结束后授权失效。</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><p>专家对话不做自动复盘，业务数据不会变成你的个人记忆。专家被下线后，已有的对话按普通助手继续。</p>',10)])])}const u=e(o,[["render",l]]);export{_ as __pageData,u as default};
